/**
 * ⚠️ PLACEHOLDER CONTENT — every project here is a stand-in.
 *
 * One project per genre, so every filter and category tile has something behind
 * it while the client's originals are on their way. Titles, dates and copy are
 * invented; media is generated by `npm run placeholders` into
 * `public/placeholder/`. Find what still needs replacing with
 * `git grep placeholder-`.
 *
 * Replacing with real work: put the files under `public/work/<slug>/`, update
 * each `src`, set the TRUE `width`/`height`, rewrite `alt` to describe the actual
 * photograph, then `npm run check:media`. Keep the matching entry in
 * `PROJECTS` in `scripts/generate-placeholders.mjs` in step (or remove it).
 *
 * `preview` (hover-loop clip) is omitted: `<HoverPreview>` falls back to a slow
 * scale on the still.
 */

import type { ImageRef, Project } from "@/types/content";

function img(src: string, alt: string, width: number, height: number): ImageRef {
  return { kind: "image", src, alt, width, height };
}

/** Placeholder gallery frames — orientation alternates as the generator draws them. */
function gallery(slug: string, title: string, count: number): ImageRef[] {
  return Array.from({ length: count }, (_, index) => {
    const i = index + 1;
    const portrait = i % 3 === 0;
    return img(
      `/placeholder/placeholder-${slug}-${String(i).padStart(2, "0")}.jpg`,
      `Placeholder — ${title}, frame ${i}`,
      portrait ? 1200 : 1800,
      portrait ? 1600 : 1200,
    );
  });
}

function cover(slug: string, title: string, portrait: boolean): ImageRef {
  return img(
    `/placeholder/placeholder-${slug}-cover.jpg`,
    `Placeholder — cover for ${title}`,
    portrait ? 1200 : 1600,
    portrait ? 1500 : 1067,
  );
}

